// Builds supabase/MASTER_SCHEMA.sql = migrations 0001..0007 in order (idempotent, safe to re-run).
// The demo sample-data seed at the end of 0006 is intentionally left out so the app starts clean.
import fs from 'node:fs';
import path from 'node:path';

const dir = path.resolve('supabase', 'migrations');
const files = fs.readdirSync(dir).filter((f) => /^\d{4}_.*\.sql$/.test(f)).sort();
const out = [
  '-- =============================================================================',
  '-- MediCheck MASTER SCHEMA  (generated by `npm run build:schema` - do not edit by hand)',
  '-- Contains migrations: ' + files.map((f) => f.slice(0, 4)).join(', '),
  '-- Safe on a brand-new Supabase project AND on a project that already ran 0001-0004:',
  '-- every statement is idempotent (IF NOT EXISTS / CREATE OR REPLACE / DROP ... IF EXISTS).',
  '-- Paste the whole file into Supabase > SQL Editor > Run.',
  '-- =============================================================================',
  '',
];
for (const f of files) {
  let sql = fs.readFileSync(path.join(dir, f), 'utf8').replace(/^\uFEFF/, '');
  if (f.startsWith('0006')) {
    const cut = sql.search(/--\s*-+\s*\r?\n--\s*7\.\s*Seed Fictional/);
    if (cut > 0) sql = sql.slice(0, cut) + '-- (sample seed data removed: start with a clean database)\n';
  }
  out.push('-- ' + '#'.repeat(77), '-- ## ' + f, '-- ' + '#'.repeat(77), '', sql.trimEnd(), '');
}
fs.writeFileSync(path.resolve('supabase', 'MASTER_SCHEMA.sql'), out.join('\n'), 'utf8');
console.log('Wrote supabase/MASTER_SCHEMA.sql from', files.join(', '));
